flowchart TD
  Q["Mira el operador de la consulta"] --> A{"¿Igualdad, rango u ORDER BY sobre valores simples?"}
  A -->|"sí"| BT["B-tree (el de siempre)"]
  A -->|"no"| B{"¿Busca elementos dentro de un valor compuesto?"}
  B -->|"array, jsonb, palabras, trozos de texto"| GIN["GIN (con pg_trgm para LIKE '%x%')"]
  B -->|"no"| C{"¿Solapamiento, contención o cercanía?"}
  C -->|"rangos, geometrías, exclusión"| GIST["GiST"]
  C -->|"no"| D{"¿Tabla enorme que crece en orden por esa columna?"}
  D -->|"sí"| BRIN["BRIN"]
  D -->|"no"| E{"¿Muchas columnas combinadas con = al azar?"}
  E -->|"sí"| BLOOM["bloom"]
  E -->|"no"| BT2["B-tree, o quizás ningún índice"]

